    <fieldset class="quiz-type-fields" data-question-type="blank" @disabled($questionType !== 'blank') @if($questionType !== 'blank') hidden @endif><legend>Accepted short answers</legend><p class="field-hint">Put ___ in the prompt where the learner fills the blank. Answers are checked automatically against this list; no manual marking or open-ended responses.</p><div data-accepted-list>@foreach(is_array($question['accepted'] ?? null) ? array_slice($question['accepted'], 0, 6) : [''] as $acceptedIndex => $accepted)<label>Accepted answer<input type="text" data-accepted-answer name="quiz_questions[{{ $questionIndex }}][accepted][{{ $acceptedIndex }}]" value="{{ is_string($accepted) ? $accepted : '' }}" maxlength="100"><button type="button" class="game-reset" data-remove-accepted>Remove answer</button></label>@endforeach</div><button type="button" class="game-reset" data-add-accepted>Add accepted answer</button><input type="hidden" data-case-default name="quiz_questions[{{ $questionIndex }}][case_sensitive]" value="0"><label class="checkbox-row"><input type="checkbox" data-case-sensitive name="quiz_questions[{{ $questionIndex }}][case_sensitive]" value="1" @checked($question['case_sensitive'] ?? false)> Letter case must match</label><p class="field-hint">Extra spaces are ignored. Letter case is ignored unless enabled.</p></fieldset>
    <fieldset class="quiz-type-fields" data-question-type="matching" @disabled($questionType !== 'matching') @if($questionType !== 'matching') hidden @endif><legend>Matching pairs</legend><p class="field-hint">Provide 2–6 unique pairs. Learners choose a match for each prompt; every pair must be correct.</p><div data-matching-pairs>@foreach(is_array($question['pairs'] ?? null) ? array_slice($question['pairs'], 0, 6) : [['id' => 'p1', 'left' => '', 'right' => ''], ['id' => 'p2', 'left' => '', 'right' => '']] as $pairIndex => $pair)@include('games.quiz-pair-fields')@endforeach</div><button class="game-reset" type="button" data-add-pair>Add a pair</button></fieldset>
